-- Event notifications are generated by trusted database triggers, not by clients.
-- Existing potential-match notifications remain in public.notifications.
create table public.activity_notifications (
  id uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references auth.users(id) on delete cascade,
  kind text not null check (kind in ('claim', 'message')),
  report_id uuid not null references public.reports(id) on delete cascade,
  claim_id uuid not null references public.claims(id) on delete cascade,
  message_id uuid unique references public.messages(id) on delete cascade,
  read_at timestamptz,
  created_at timestamptz not null default now(),
  constraint activity_notification_event_shape check (
    (kind = 'claim' and message_id is null)
    or (kind = 'message' and message_id is not null)
  ),
  constraint activity_notification_once_per_claim unique (claim_id, kind, message_id)
);
create unique index activity_notifications_claim_once_idx on public.activity_notifications(claim_id) where kind = 'claim';
create index activity_notifications_recipient_idx
  on public.activity_notifications(recipient_id, created_at desc);

alter table public.activity_notifications enable row level security;
revoke all on public.activity_notifications from public, anon, authenticated;
grant select on public.activity_notifications to authenticated;
grant update (read_at) on public.activity_notifications to authenticated;
create policy "Read my activity alerts" on public.activity_notifications
  for select to authenticated using (
    recipient_id = (select auth.uid())
    and coalesce((select (auth.jwt()->>'is_anonymous')::boolean), true) = false
  );
create policy "Mark my activity alerts read" on public.activity_notifications
  for update to authenticated
  using (
    recipient_id = (select auth.uid())
    and coalesce((select (auth.jwt()->>'is_anonymous')::boolean), true) = false
  )
  with check (
    recipient_id = (select auth.uid())
    and coalesce((select (auth.jwt()->>'is_anonymous')::boolean), true) = false
  );

create function public.notify_on_claim_created()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_finder uuid;
begin
  select r.user_id into v_finder from public.reports r
    where r.id = new.report_id and r.report_type = 'found';
  if v_finder is not null and v_finder <> new.claimant_id then
    insert into public.activity_notifications(recipient_id,kind,report_id,claim_id)
      values(v_finder,'claim',new.report_id,new.id);
  end if;
  return new;
end;
$$;
create trigger notify_finder_new_claim
  after insert on public.claims
  for each row execute function public.notify_on_claim_created();

create function public.notify_on_message_created()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_claimant uuid;
  v_finder uuid;
  v_report uuid;
  v_recipient uuid;
begin
  select c.claimant_id, r.user_id, c.report_id
    into v_claimant, v_finder, v_report
    from public.claims c
    join public.reports r on r.id = c.report_id
    where c.id = new.claim_id and r.report_type = 'found'
      and c.status in ('pending','approved');
  if v_claimant is null then return new; end if;

  if new.sender_id = v_claimant then
    v_recipient := v_finder;
  elsif new.sender_id = v_finder then
    v_recipient := v_claimant;
  else
    return new;
  end if;

  if v_recipient is not null and v_recipient <> new.sender_id then
    insert into public.activity_notifications(recipient_id,kind,report_id,claim_id,message_id)
      values(v_recipient,'message',v_report,new.claim_id,new.id);
  end if;
  return new;
end;
$$;
create trigger notify_other_participant_new_message
  after insert on public.messages
  for each row execute function public.notify_on_message_created();

revoke all on function public.notify_on_claim_created() from public, anon, authenticated;
revoke all on function public.notify_on_message_created() from public, anon, authenticated;
